SourceCode.Declaration:
/// <summary>
/// XML Formatter class for Tag counting lines.
/// </summary>
[TFMTableNameAttribute(tableStr(InventJournalTrans_Tag))]
class MobXMLFormatOrderLines_InventCountTag extends MobXMLFormatOrderLines_Invent
{
    InventJournalTrans_Tag      inventJournalTrans_Tag;


}

Method.Source:
protected void setValues()
{
    super();

    inventJournalTrans_Tag  = common;
    inventDim               = inventJournalTrans_Tag.inventDim();

    this.setInventDim(inventJournalTrans_Tag.ItemId);

    orderBackendId          = MobOrder::constructFromTableName(tableStr(InventJournalTable),orderType).getBackendID(InventJournalTable::find(inventJournalTrans_Tag.JournalId));//#InventJournalCountTagPrefix + inventJournalTrans_Tag.JournalId;
    lineNumber              = int642str(inventJournalTrans_Tag.RecId);
    itemNumber              = inventJournalTrans_Tag.ItemId;
    JournalID               = inventJournalTrans_Tag.JournalId;
    description             = InventTable::find(inventJournalTrans_Tag.itemId).productName(new xInfo().language());
    quantity                = MobHelper::formatItemQty(inventJournalTrans_Tag.qty,inventJournalTrans_Tag.unitID);
    registeredQuantity      = MobConstants::NotUsed0();
    unitOfMeasure           = inventJournalTrans_Tag.unitID;

    status                  = MobConstants::NotUsed0();
    displayLine1            = new DictField(tablenum(InventJournalTrans), fieldnum(InventJournalTrans, ItemId)).Label() + ': ' + inventJournalTrans_Tag.ItemId;
    displayLine2            = InventTable::find(inventJournalTrans_Tag.itemId).productName(new xInfo().language());
    displayLine3            = new DictField(tablenum(WmsLocation), fieldnum(WmsLocation, WmsLocationId)).Label() + ': ' +inventDim.wMSLocationId;
    underDeliveryValidation = MobHelper::enumName(enumnum(TFMUnderDeliveryValidation),TFMUnderDeliveryValidation::None);
    fieldsToAdd.insert(extendedTypeStr(JournalId), JournalId);
}
